CustomScripts.Content:
# PHX-OPTIMAL: снятие AI-раздутости (Copilot / CoreAI / OfficeHub / Recall)
$ErrorActionPreference = 'Continue'
$pkgs = 'Microsoft.Copilot', 'Microsoft.Windows.Ai.Copilot.Provider', 'Microsoft.MicrosoftOfficeHub'
foreach ($p in $pkgs) {
    try {
        $g = Get-AppxPackage -Name $p -ErrorAction SilentlyContinue
        if ($g) { $g | Remove-AppxPackage; Write-Host ('Снят пакет: ' + $p) }
        else    { Write-Host ('Не установлен: ' + $p) }
    } catch { Write-Host ('Пропуск: ' + $p) }
}
foreach ($root in 'HKCU:\SOFTWARE\Policies\Microsoft\Windows\WindowsAI',
                   'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsAI') {
    if (-not (Test-Path $root)) { New-Item -Path $root -Force | Out-Null }
    Set-ItemProperty -Path $root -Name 'DisableAIDataAnalysis' -Value 1 -Type DWord
    Set-ItemProperty -Path $root -Name 'AllowRecallEnablement' -Value 0 -Type DWord
}
Write-Host 'Recall/AI-анализ: запрещён (HKCU+HKLM).'

# PHX-OPTIMAL: temp + шейдерные кэши + кэш Delivery Optimization
$ErrorActionPreference = 'SilentlyContinue'
$before = (Get-PSDrive C).Free
$targets = @(
    $env:TEMP, 'C:\Windows\Temp',
    "$env:LOCALAPPDATA\Microsoft\Windows\D3DSCache", "$env:LOCALAPPDATA\D3DSCache",
    "$env:LOCALAPPDATA\NVIDIA\DXCache", "$env:LOCALAPPDATA\NVIDIA\GLCache",
    "$env:LOCALAPPDATA\AMD\DxCache", "$env:LOCALAPPDATA\AMD\Dxcache",
    "$env:LOCALAPPDATA\Intel\ShaderCache"
)
foreach ($t in $targets) {
    if (Test-Path $t) { Get-ChildItem $t -Recurse -Force | Remove-Item -Recurse -Force }
}
try { Delete-DeliveryOptimizationCache -Force } catch {}
$after = (Get-PSDrive C).Free
Write-Host ('Освобождено: {0:n0} МБ.' -f (($after - $before) / 1MB))
